//! Short interpolation chains (H1) of the multistage upsampler: the long filter runs at the source rate, and these
//! linear-phase stages take its output up to the output rate.
//!
//! Generated by `fir-optimizer/multistage/design_h1.py`; do not edit. Each stage is a Kaiser-windowed sinc, flat to
//! the wall + 5 Hz (at 44.1 kHz, scaled with the rate) within 1e-9 and below -210 dB from the first image up to the
//! output Nyquist; the values are rounded once from 40-digit sums, so the file is the same on every machine.
#![cfg_attr(not(test), allow(dead_code))]

/// One stage of a short chain: upsample by `ratio` through linear-phase, odd-length `taps` whose sum is `ratio`
/// (unit gain at DC after zero stuffing). Half-band stages keep their zero taps here; the engine skips them.
#[derive(Debug)]
pub struct H1Stage {
    pub ratio: usize,
    pub taps: &'static [f64],
}

static CASCADE_X2_44K: [H1Stage; 1] = [
    H1Stage { ratio: 2, taps: &HB1_44K },
];
static CASCADE_X4_44K: [H1Stage; 2] = [
    H1Stage { ratio: 2, taps: &HB1_44K },
    H1Stage { ratio: 2, taps: &HB2_44K },
];
static CASCADE_X8_44K: [H1Stage; 2] = [
    H1Stage { ratio: 2, taps: &HB1_44K },
    H1Stage { ratio: 4, taps: &P4_44K },
];
static CASCADE_X16_44K: [H1Stage; 2] = [
    H1Stage { ratio: 2, taps: &HB1_44K },
    H1Stage { ratio: 8, taps: &P8_44K },
];
static CASCADE_X32_44K: [H1Stage; 2] = [
    H1Stage { ratio: 2, taps: &HB1_44K },
    H1Stage { ratio: 16, taps: &P16_44K },
];
static CASCADE_X2_48K: [H1Stage; 1] = [
    H1Stage { ratio: 2, taps: &HB1_48K },
];
static CASCADE_X4_48K: [H1Stage; 2] = [
    H1Stage { ratio: 2, taps: &HB1_48K },
    H1Stage { ratio: 2, taps: &HB2_48K },
];
static CASCADE_X8_48K: [H1Stage; 2] = [
    H1Stage { ratio: 2, taps: &HB1_48K },
    H1Stage { ratio: 4, taps: &P4_48K },
];
static CASCADE_X16_48K: [H1Stage; 2] = [
    H1Stage { ratio: 2, taps: &HB1_48K },
    H1Stage { ratio: 8, taps: &P8_48K },
];
static CASCADE_X32_48K: [H1Stage; 2] = [
    H1Stage { ratio: 2, taps: &HB1_48K },
    H1Stage { ratio: 16, taps: &P16_48K },
];

/// The chain for a source of the 44.1 kHz family (`base_rate` 44100: 44.1/88.2/176.4k) or of the 48 kHz family
/// (48000: 48/96/192k) upsampled by `ratio`; the stage ratios multiply to `ratio`. `None` = no chain for it.
pub fn h1_chain(base_rate: u32, ratio: usize) -> Option<&'static [H1Stage]> {
    Some(match (base_rate, ratio) {
        (44100, 2) => &CASCADE_X2_44K,
        (44100, 4) => &CASCADE_X4_44K,
        (44100, 8) => &CASCADE_X8_44K,
        (44100, 16) => &CASCADE_X16_44K,
        (44100, 32) => &CASCADE_X32_44K,
        (48000, 2) => &CASCADE_X2_48K,
        (48000, 4) => &CASCADE_X4_48K,
        (48000, 8) => &CASCADE_X8_48K,
        (48000, 16) => &CASCADE_X16_48K,
        (48000, 32) => &CASCADE_X32_48K,
        _ => return None,
    })
}

/// Every chain generated for (`base_rate`, `ratio`), named by its kind: the shipped one, and the one-stage
/// chain while the quality gate compares them.
#[cfg(test)]
pub fn candidates(base_rate: u32, ratio: usize) -> Vec<(&'static str, &'static [H1Stage])> {
    match (base_rate, ratio) {
        (44100, 2) => vec![("cascade", &CASCADE_X2_44K)],
        (44100, 4) => vec![("cascade", &CASCADE_X4_44K)],
        (44100, 8) => vec![("cascade", &CASCADE_X8_44K)],
        (44100, 16) => vec![("cascade", &CASCADE_X16_44K)],
        (44100, 32) => vec![("cascade", &CASCADE_X32_44K)],
        (48000, 2) => vec![("cascade", &CASCADE_X2_48K)],
        (48000, 4) => vec![("cascade", &CASCADE_X4_48K)],
        (48000, 8) => vec![("cascade", &CASCADE_X8_48K)],
        (48000, 16) => vec![("cascade", &CASCADE_X16_48K)],
        (48000, 32) => vec![("cascade", &CASCADE_X32_48K)],
        _ => Vec::new(),
    }
}

