#[cfg(test)]
mod tests {
    use super::*;

    fn check(base: u32, ratio: usize, chain: &[H1Stage]) {
        assert_eq!(chain.iter().map(|s| s.ratio).product::<usize>(), ratio);
        for s in chain {
            let n = s.taps.len();
            assert_eq!(n % 2, 1, "{base} x{ratio}: odd length");
            for i in 0..n / 2 {
                assert_eq!(s.taps[i].to_bits(), s.taps[n - 1 - i].to_bits(), "{base} x{ratio}: symmetric");
            }
            let sum: f64 = s.taps.iter().sum();
            assert!((sum - s.ratio as f64).abs() < 1e-12, "{base} x{ratio}: DC gain {sum}");
            // Every polyphase branch passes DC at unit gain.
            for p in 0..s.ratio {
                let b: f64 = s.taps[p..].iter().step_by(s.ratio).sum();
                assert!((b - 1.0).abs() < 1e-10, "{base} x{ratio}: branch {p} DC gain {b}");
            }
            if s.ratio == 2 {
                // A half-band: its centre's branch is the centre tap alone, exactly 1.
                let m = (n - 1) / 2;
                assert_eq!(s.taps[m], 1.0, "{base} x{ratio}: half-band centre");
                for k in (2..=m).step_by(2) {
                    assert_eq!(s.taps[m + k], 0.0, "{base} x{ratio}: half-band zero at {k}");
                }
            }
        }
    }

    #[test]
    fn every_chain_is_linear_phase_and_multiplies_to_its_ratio() {
        for base in [44_100u32, 48_000] {
            for ratio in [2usize, 4, 8, 16, 32] {
                let chain = h1_chain(base, ratio).unwrap_or_else(|| panic!("{base} x{ratio}: no chain"));
                check(base, ratio, chain);
                for (_, c) in candidates(base, ratio) {
                    check(base, ratio, c);
                }
            }
            assert!(h1_chain(base, 3).is_none() && h1_chain(base, 64).is_none());
        }
        assert!(h1_chain(44_100 * 2, 2).is_none(), "a family is named by its base rate");
    }
}
